// ---- deterministic hash ---------------------------------------------------------------------------------------------
function hash(x, z, c, seed, salt = 0) {
  let h = (Math.imul(x | 0, 0x9e3779b1) ^ Math.imul(z | 0, 0x85ebca6b) ^ Math.imul(c | 0, 0xc2b2ae35) ^ Math.imul((seed | 0) + 0x1234567, 0x27d4eb2f) ^ Math.imul(salt + 1, 0x165667b1)) >>> 0;
  h ^= h >>> 15; h = Math.imul(h, 0x2c1b3c6d) >>> 0; h ^= h >>> 12; h = Math.imul(h, 0x297a2d39) >>> 0; h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}
const seedOf = (s) => (typeof s === "number" ? s : [...String(s ?? 0)].reduce((a, ch) => (Math.imul(a, 31) + ch.charCodeAt(0)) | 0, 7));

// ---- autoMix -------------------------------------------------------------------------------------------------------
/** The block 60% + two same-family stair-capable members 25/15 (nearest in the family's clean -> worn order, topped up
 *  with the nearest-coloured stair-capable block when the family is short). Never returns members without stairs. */
export function autoMix(block) {
  const b = strip(block), self = prefixOf(b);
  const fam = family(b === self ? (colour(b) ? b : self) : b).map(prefixOf);
  const at = fam.indexOf(self);
  const near = fam.map((m, i) => ({ m, d: Math.abs(i - (at < 0 ? 0 : at)) })).filter(({ m }) => m !== self && canStair(m)).sort((p, q) => p.d - q.d).map((e) => e.m);
  const out = [self, ...new Set(near)];
  if (out.length < 3 && colour(self)) {
    const c = colour(self);
    const rest = [...STAIR_SLAB].filter((m) => !out.includes(m) && colour(m)).map((m) => ({ m, d: toneDistance(c, colour(m)) })).filter((e) => e.d > 0.02 && e.d < 0.5).sort((p, q) => p.d - q.d);
    for (const { m } of rest) if (out.length < 3) out.push(m);
  }
  const w = [60, 25, 15];
  return out.slice(0, 3).map((m, i, a) => [m, a.length === 1 ? 100 : a.length === 2 ? [70, 30][i] : w[i]]);
}

// ---- textureOf -----------------------------------------------------------------------------------------------------
const ROLES = ["eave", "ridge", "verge", "fascia", "soffit"];
function normalise(spec) {
  if (typeof spec === "string") {
    const key = strip(spec);
    if (ROOF_PALETTES[key]) return { ...ROOF_PALETTES[key] };
    return { mix: autoMix(key) };
  }
  if (!spec || !Array.isArray(spec.mix) || !spec.mix.length) throw new Error("roof texture: spec needs a palette name, a block, or { mix:[[block, weight], ...] }");
  return { ...spec };
}
